## The production answer

```jsx
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, useSortable, arrayMove } from '@dnd-kit/sortable';

function List({ items, setItems }) {
  return (
    <DndContext
      collisionDetection={closestCenter}
      onDragEnd={({ active, over }) => {
        if (over && active.id !== over.id) {
          const from = items.findIndex((i) => i.id === active.id);
          const to = items.findIndex((i) => i.id === over.id);
          setItems(arrayMove(items, from, to));
        }
      }}
    >
      <SortableContext items={items}>
        {items.map((item) => <SortableRow key={item.id} item={item} />)}
      </SortableContext>
    </DndContext>
  );
}
```

**dnd-kit** is built on Pointer Events, ships keyboard sortables and live-region announcements, and is the current default. `react-beautiful-dnd` is no longer maintained.

