## The viewport

```jsx
function ToastViewport({ toasts, onDismiss }) {
  return createPortal(
    <div className="toast-viewport">
      {toasts.map((t) => <Toast key={t.id} {...t} onDismiss={onDismiss} />)}
    </div>,
    document.body
  );
}

function Toast({ id, message, type, duration, onDismiss }) {
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (paused || duration === Infinity) return;
    const timer = setTimeout(() => onDismiss(id), duration);
    return () => clearTimeout(timer);
  }, [id, duration, paused, onDismiss]);

  return (
    <div
      role={type === 'error' ? 'alert' : 'status'}
      aria-live={type === 'error' ? 'assertive' : 'polite'}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocusCapture={() => setPaused(true)}
      onBlurCapture={() => setPaused(false)}
    >
      {message}
      <button onClick={() => onDismiss(id)} aria-label="Dismiss">×</button>
    </div>
  );
}
```

Note the timer restarts when `paused` flips back — acceptable, and simpler than tracking remaining time. Say you know the trade-off.

