## Stopwatch with pause

```jsx
function useStopwatch() {
  const [elapsed, setElapsed] = useState(0);
  const [running, setRunning] = useState(false);
  const startRef = useRef(0);          // when the current run began
  const accumulatedRef = useRef(0);    // total from previous runs

  useEffect(() => {
    if (!running) return;
    startRef.current = Date.now();

    const id = setInterval(() => {
      setElapsed(accumulatedRef.current + (Date.now() - startRef.current));
    }, 50);

    return () => {
      clearInterval(id);
      accumulatedRef.current += Date.now() - startRef.current;   // bank it on pause
    };
  }, [running]);

  return {
    elapsed,
    running,
    start: () => setRunning(true),
    pause: () => setRunning(false),
    reset: () => { accumulatedRef.current = 0; setElapsed(0); setRunning(false); },
  };
}
```

The two-ref split — banked time plus current-run start — is the clean way to handle pause and resume.

